@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def get_sim_gantry_target_textfield() -> str:
    """Locates the main Sim Dialogs window > then reads the data in the Target textfield only if the object exists
    """
    if SimDialogMainFuncs.find_main_sim_dialogs_window():
        text_value = CommonActions.get_uneditable_field_objects_text_value(SimDialogsObjects.sim_Gantry_Target_Field)
        if text_value is not None:
            return text_value
    return ""

