@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def edit_sim_gantry_target_textfield(valueToSet: str) -> None:
    """Locates the main Sim Dialogs window > clears the existing text in the Target field and enters the specified text
    """
    if SimDialogMainFuncs.find_main_sim_dialogs_window():
       CommonActions.left_click_object_no_move(SimDialogsObjects.sim_Gantry_Target_Field)
       CommonActions.press_key_sequence_ctrl_a()
       CommonActions.press_delete_key()
       CommonActions.type_in_textfield(SimDialogsObjects.sim_Gantry_Target_Field, valueToSet)

